class AudioBus {
 constructor(g){this.g=g;this.ctx=null;this.music=new MusicPlayer(g)}
 tone(hz,duration=.08,volume=.025){if(!this.g.state.settings.sound)return;try{this.ctx||=new(window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume();const o=this.ctx.createOscillator(),v=this.ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(hz,this.ctx.currentTime);v.gain.setValueAtTime(volume,this.ctx.currentTime);v.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);o.connect(v);v.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration)}catch{}}
 attack(type){this.tone(({fire:160,water:380,grass:490,electric:720,ghost:210})[type]||280,.065,.018)}
 chime(rarity){const base=rarity==='legendary'?440:rarity==='epic'?370:300;[0,4,7,12].forEach((n,i)=>setTimeout(()=>this.tone(base*2**(n/12),.17,.025),i*105))}
}
class GameApp {
 constructor(dex,chart,progression){this.dex=dex;this.progression=progression;this.chart=chart;this.items=ITEMS;let raw;try{raw=JSON.parse(localStorage.getItem('tour-infernale-v1'))}catch{}this.state=migrate(raw);this.ticketGift=applyReleaseGift(this.state,raw);const excluded=this.state.roster.filter(k=>!dex[parseInt(k)]||(k.endsWith('s')&&!dex[parseInt(k)]?.shiny));this.state.archivedRoster=[...new Set([...this.state.archivedRoster,...excluded])];this.state.roster=this.state.roster.filter(k=>!excluded.includes(k));this.state.team=this.state.team.filter(k=>this.state.roster.includes(k));if(!this.state.team.length)this.state.team=this.state.roster.slice(0,1);if(!dex[this.state.starter])this.state.starter=parseInt(this.state.roster[0])||null;if(!this.state.roster.includes(this.state.survivor))this.state.survivor=this.state.roster[0]||null;this.root=document.querySelector('#content');this.modeRoot=document.querySelector('#mode-root');this.modal=document.querySelector('#modal');this.page='home';this.modalOptions={};this.audio=new AudioBus(this);this.net=new PartyNetwork(this);this.survival=new Survival(this);this.battle=new TowerBattle(this);this.duel=new Duel(this);this.arena=new ArenaBattle(this);this.library=new PokemonLibrary(this);this.shop=new DailyShop(this,progression);this.evolutions=new EvolutionManager(this);this.lab=new PokemonLab(this);this.cinema=new LegendaryCinema(this);this.summoning=new Summoning(this);this.afk=new AfkZone(this);this.conquest=new Conquest(this);this.mode=null;this.uiRaf=0;this.currentStarterGen=0;this.save();this.bind();this.route('home');if(!this.state.starter)this.openStarter();if(this.ticketGift)setTimeout(()=>this.toast('Cadeau reçu : +1 000 tickets universels !'),650)}
 poke(key){return this.dex[idOf(key)]||{id:0,name:'Pokémon',types:[],moves:[],rarity:'common',stats:[]}}
 held(key){return held(this.state,key)}
 rarity(key){return RATES.find(r=>r.key===key)||RATES[0]}
 escape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
 save(){try{localStorage.setItem('tour-infernale-v1',JSON.stringify(this.state))}catch{this.toast('Le navigateur ne peut pas enregistrer la progression. Exporte ta sauvegarde depuis les réglages.')}this.wallet()}
 wallet(){const el=document.querySelector('#tickets');if(el)el.textContent=this.state.tickets;const c=document.querySelector('#coins');if(c)c.textContent=this.state.coins;const avatar=document.querySelector('#top-avatar');if(avatar){avatar.src=trainerSrc(this.state.player.avatar);avatar.alt=this.state.player.name}}
 toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
 heading(k,title,desc){return `<div class="page-heading"><span class="eyebrow">${k}</span><h1>${title}</h1><p>${desc}</p></div>`}
 image(key,cls=''){return `<img class="${cls}" src="${Art.icon(key)}" alt="${this.escape(this.poke(key).name)}" loading="lazy">`}
 monCards(keys,action,selected=[]){return keys.map(key=>{const p=this.poke(key);return `<button class="mon-card ${selected.includes(key)?'selected':''} ${isShiny(key)?'shiny-card':''}" data-act="${action}" data-key="${key}" data-card-name="${this.escape(p.name.toLowerCase())}"><small>#${String(p.id).padStart(3,'0')} ${isShiny(key)?'✧ SHINY':''}</small><canvas width="130" height="105" data-mon="${key}"></canvas><b>${p.name}</b><span>Niv. ${level(profile(this.state,key))} · ${p.types.map(t=>Art.TYPE_NAMES[t]).join(' / ')}</span>${selected.includes(key)?'<i>✓ Sélectionné</i>':''}</button>`}).join('')}
 route(page){if(this.mode)return;if(this.page==='pvp'&&page!=='pvp')this.duel.clean();if(page==='afk'){this.afk.open();return;}this.page=page;this.audio.music.setScene(page);document.body.dataset.page=page;document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#breadcrumb').textContent=({home:'Le sanctuaire',survival:'Expéditions',gacha:'Invocations',collection:'Collection',team:'Mon équipe',inventory:'Sac & objets',friends:'Salon des alliés',tower:'Tour Infernale',den:'L’Antre',pvp:'Combats Pokémon',profile:'Profil de dresseur',conquest:'Conquête',shop:'Boutique quotidienne'})[page]||page;this.render();window.scrollTo(0,0)}
 render(){cancelAnimationFrame(this.uiRaf);const views={shop:()=>this.shop.render(),conquest:()=>this.conquest.render(),home:()=>this.home(),tower:()=>this.towerSetup(),den:()=>denPage(this),profile:()=>profilePage(this),pvp:()=>this.duel.render(),survival:()=>this.survivalSetup(),gacha:()=>this.summoning.render(),collection:()=>this.collection(),team:()=>this.team(),inventory:()=>this.inventory(),friends:()=>this.friends()};this.root.innerHTML=(views[this.page]||views.home)();this.wallet();this.startUIAnimation();this.conquest.afterRender();this.root.querySelectorAll('canvas[data-arena-preview]').forEach(c=>drawArenaPreview(c,c.dataset.arenaPreview))}
 home(){return worldHome(this)}
 towerSetup(){return this.heading('LA TOUR INFERNALE','Tour de combat','Gravis les étages en affrontant des dresseurs IA et leurs équipes de Pokémon.')+`<section class="panel tower-intro"><span class="eyebrow">ÉTAGE ${this.state.floor}</span><h2>Un nouveau dresseur t’attend</h2><p>Prépare six Pokémon, adapte leurs attaques et remporte le combat pour continuer ton ascension.</p><button class="primary" data-act="start-battle">Affronter le dresseur IA ↗</button><button data-act="route" data-page="team">Préparer mon équipe</button><button data-act="arena-solo">Essayer le combat Arène 2D ↗</button></section>`}
 legacyHome(){const key=this.state.survivor||'4',boss=String([94,6,249,150,384,487][(this.state.floor-1)%6]);return `<section class="tower-hero"><canvas id="tower-art" width="960" height="480" aria-label="La Tour Infernale dans les montagnes de cendre"></canvas><div class="hero-grain"></div><div class="hero-content"><div class="season-tag"><i></i> CHAPITRE I · LES GARDIENS DE CENDRE</div><h1>LA TOUR<br><em>INFERNALE</em></h1><p>Au-delà des braises, un nouveau gardien t’attend.<br>Prépare ton équipe. Rassemble tes alliés.<br>Le prochain étage vous appartient.</p><div class="hero-buttons"><button class="primary" data-act="start-battle">♜ Entrer dans la tour <span>↗</span></button><button data-act="route" data-page="survival">Explorer les terres de cendre</button></div><div class="hero-caption"><span>ÉTAGE <b>${String(this.state.floor).padStart(2,'0')}</b></span><i></i><span>JUSQU’À 4 DRESSEURS</span></div></div><div class="hero-floor"><span>PROCHAIN GARDIEN</span><strong>${this.poke(boss).name}</strong><small>Étage ${String(this.state.floor).padStart(2,'0')}</small><canvas width="120" height="100" data-mon="${boss}"></canvas></div></section><div class="home-stats"><div><i>♜</i><span>Ton ascension<strong>Étage ${String(this.state.floor).padStart(2,'0')}</strong></span></div><div><i>◈</i><span>Ta collection<strong>${this.state.roster.length} partenaire${this.state.roster.length>1?'s':''}</strong></span></div><div><i>✧</i><span>Variantes chromatiques<strong>${this.state.roster.filter(isShiny).length} shiny${this.state.roster.filter(isShiny).length>1?'s':''}</strong></span></div></div><div class="home-grid"><section class="panel team-panel"><div class="section-title"><div><span class="eyebrow">LA FORCE DU LIEN</span><h2>Ton équipe de la tour</h2></div><button class="text-button" data-act="route" data-page="team">Préparer →</button></div><div class="home-team">${this.state.team.map(k=>`<button data-act="inspect" data-key="${k}"><canvas width="110" height="90" data-mon="${k}"></canvas><span>${this.poke(k).name}${isShiny(k)?' ✧':''}</span></button>`).join('')}${Array.from({length:6-this.state.team.length},()=>'<div class="team-empty">＋<small>À recruter</small></div>').join('')}</div><p class="muted">Un Pokémon actif, cinq en réserve. Chaque dresseur apporte sa propre équipe.</p></section><section class="panel expedition-card"><div><span class="eyebrow">LE BUTIN DES EXPLORATEURS</span><h2>Les terres de cendre</h2><p>Quatre attaques. Des vagues de Pokémon.<br>Des coffres cachés dans la pénombre.</p><button data-act="route" data-page="survival">Partir en expédition ↗</button></div><canvas width="150" height="140" data-mon="${key}"></canvas></section></div>`}
 survivalSetup(){const key=this.state.survivor,item=this.held(key);return this.heading('LES TERRES AU PIED DE LA TOUR','Expédition de survie','Un seul partenaire, quatre attaques et une forêt de ruines à explorer.')+`<section class="panel"><div class="section-title"><h2>Choisis ton partenaire</h2><span>1 Pokémon sélectionné</span></div>${this.library.render('survival','select-survivor',[key])}<div class="expedition-info"><div><i>1–4</i><h3>Quatre attaques</h3><p>Change d’attaque à tout moment. Elle se déclenche automatiquement sur les ennemis proches.</p></div><div><i>▱</i><h3>Tickets universels</h3><p>Un ticket toutes les 20 secondes, utilisable sur n’importe quel portail.</p></div><div><i>◈</i><h3>Des trésors à trouver</h3><p>Ouvre les coffres avec E. Conserve les objets et équipe tes Pokémon au camp.</p></div></div><div class="loadout-summary"><span>${item.name?'Objet tenu : <b>'+item.name+'</b> · '+item.desc:'Aucun objet tenu · Explore pour trouver les coffres, désormais plus rares.'}</span><button class="text-button" data-act="route" data-page="inventory">Gérer les objets →</button></div><div class="launch-row"><button class="primary" data-act="start-run">Lancer l’expédition <span>⛶</span></button><span>Plein écran · ZQSD / WASD / flèches · 1–4 : attaques</span></div></section>`}
 collection(){return this.heading('LE REGISTRE DES COMPAGNONS','Ta collection',`${this.state.roster.length} variantes obtenues. Filtre tes compagnons et découvre ceux qui te manquent.`)+this.library.render('collection','inspect')}
 team(){return this.heading('AVANT DE FRANCHIR LES PORTES','Ton équipe de la tour','Sélectionne jusqu’à six Pokémon. Chacun peut porter trois objets différents.')+`<div class="team-ribbon"><strong>${this.state.team.length} / 6 sélectionnés</strong><span>Un actif · Cinq réservistes</span><button class="primary" data-act="start-battle">Entrer dans la tour ↗</button></div>${this.library.render('team','toggle-team',this.state.team)}`}
 inventory(){return this.shop.bag()+equipmentInventory(this)}
 friends(){const n=this.net;return this.heading('L’ASCENSION SE PARTAGE','Le salon des alliés','Jusqu’à quatre dresseurs. Six Pokémon chacun. Un boss de l’Antre à vaincre ensemble.')+`<div class="friends-grid"><section class="panel"><span class="eyebrow">OUVRIR LES PORTES</span><h2>Créer un salon</h2><p>Invite tes amis et composez vos équipes avant de lancer le raid.</p><button class="primary" data-act="create-room">Créer mon salon</button>${n.peer?.id&&!n.guest?`<div class="room-code"><small>CODE DU SALON</small><strong>${this.escape(n.peer.id)}</strong><button data-act="copy-room">Copier le code</button></div><div class="room-players"><span>Toi · ${this.state.team.length} Pokémon</span>${n.players.map(p=>`<span>${this.escape(p.name)} · ${p.keys.length} Pokémon prêts</span>`).join('')}</div><button class="primary" data-act="start-den">Lancer le raid · ${1+n.players.length}/4</button>`:''}</section><section class="panel"><span class="eyebrow">REJOINDRE SES ALLIÉS</span><h2>Tu as un code ?</h2><p>Prépare ton équipe, puis entre le code partagé par l’hôte.</p><input id="room-code" placeholder="Code du salon" aria-label="Code du salon"><button data-act="join-room">Rejoindre le salon ↗</button><p class="network-status">${this.escape(n.status)}</p><button class="text-button" data-act="route" data-page="team">Préparer mes six Pokémon →</button><p class="muted">Connexion directe entre navigateurs. L’hôte doit garder le jeu ouvert. Le site doit être accessible à chacun des invités.</p></section></div>`}
 showResult(k,title,desc,key,reward,sub,buttons){this.page='result';this.root.innerHTML=this.heading(k,title,desc)+`<section class="panel game-result"><canvas width="230" height="190" data-mon="${key}"></canvas><h2>${reward}</h2><p>${sub}</p><div>${buttons.map(([page,label],i)=>`<button class="${i===0?'primary':''}" data-act="route" data-page="${page}">${label}</button>`).join('')}</div></section>`;this.startUIAnimation()}
 startUIAnimation(){cancelAnimationFrame(this.uiRaf);const world=this.root.querySelector('#world-art'),tower=this.root.querySelector('#tower-art'),canvases=[...this.root.querySelectorAll('canvas[data-mon]')];Art.preload(canvases.map(c=>c.dataset.mon));let last=0;const loop=t=>{if(this.mode)return;this.uiRaf=requestAnimationFrame(loop);if(document.hidden||t-last<45)return;last=t;const time=this.state.settings.reducedMotion?0:t/1000;if(world?.isConnected)worldScene(world.getContext('2d'),world.width,world.height,time);if(tower?.isConnected)Art.towerScene(tower.getContext('2d'),tower.width,tower.height,time);for(const c of canvases){if(!c.isConnected)continue;const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);Art.drawMon(x,c.dataset.mon,c.width/2,c.height/2,Math.min(c.width,c.height)*.9,'Idle',0,time)}};this.uiRaf=requestAnimationFrame(loop)}
 openModal(html,options={}){this.modalOptions=options;this.modal.className=options.className||(this.mode==='survival'?'survival-dialog':this.summoning?.busy?'summon-dialog':'');this.modal.innerHTML=(options.locked?'':'<button class="modal-close" data-act="close-modal" aria-label="Fermer">×</button>')+html;if(!this.modal.open)this.modal.showModal()}
 closeModal(force=false){if(this.modalOptions.locked&&!force)return;const options=this.modalOptions;this.modalOptions={};this.modal.close();options.onClose?.()}
 requireStarter(){if(this.state.starter)return true;this.openStarter();return false}
 openStarter(gen=0){this.currentStarterGen=gen;this.openModal(`<div class="starter-title"><span class="eyebrow">TA PREMIÈRE ALLIANCE</span><h2>Qui gravira la tour avec toi ?</h2><p>Choisis ton premier compagnon parmi les starters des neuf régions.</p></div><div class="region-tabs starter-tabs">${REGIONS.map((r,i)=>`<button class="${i===gen?'selected':''}" data-act="starter-region" data-gen="${i}">${r}</button>`).join('')}</div><div class="mon-grid starter-grid">${this.monCards([...STARTERS[gen],...(gen===0?[25,133]:[])].filter(id=>this.dex[id]).map(String),'choose-starter')}</div>`,{locked:true});let raf;const canvases=[...this.modal.querySelectorAll('canvas')];Art.preload(canvases.map(c=>c.dataset.mon));const loop=t=>{if(!canvases[0]?.isConnected||!this.modal.open)return;for(const c of canvases){const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);Art.drawMon(x,c.dataset.mon,c.width/2,c.height/2,90,'Idle',0,t/1000)}raf=requestAnimationFrame(loop)};raf=requestAnimationFrame(loop)}
 chooseStarter(key){if(this.state.starter||![...STARTERS.flat(),25,133].includes(idOf(key)))return;this.state.starter=idOf(key);this.state.roster=[...new Set([...this.state.roster,key])];this.state.team=[key];this.state.survivor=key;this.save();this.closeModal(true);this.route('home');this.audio.chime('rare');this.toast(this.poke(key).name+' rejoint ton aventure !')}
 inspect(key){this.lab.open(key)}
 enterMode(mode){cancelAnimationFrame(this.uiRaf);this.mode=mode;this.audio.music.setScene(mode==='battle'&&this.battle.active&&this.battle.data?.kind==='den'?'den':mode);document.body.classList.add('in-mode');this.modeRoot.hidden=false;this.modeRoot.dataset.mode=mode;this.requestFullscreen()}
 requestFullscreen(){if(!document.fullscreenElement&&document.documentElement.requestFullscreen){try{const p=document.documentElement.requestFullscreen();p?.then(()=>this.ownsFullscreen=true).catch(()=>{})}catch{}}}
 leaveMode(){this.mode=null;this.audio.music.setScene(this.page);this.modeRoot.hidden=true;this.modeRoot.innerHTML='';document.body.classList.remove('in-mode');if(document.fullscreenElement&&this.ownsFullscreen){document.exitFullscreen?.().catch(()=>{});this.ownsFullscreen=false}this.wallet()}
 settings(){this.openModal(`<span class="eyebrow">TON AVENTURE</span><h2>Réglages</h2><div class="setting-row"><span>Musique d’ambiance · touche M</span><button data-act="toggle-music">${this.state.settings.music?'Activée':'Désactivée'}</button></div><label class="music-volume"><input id="music-volume" type="range" min="0" max="100" value="${Math.round(this.state.settings.musicVolume*100)}" aria-label="Volume de la musique"><output id="music-volume-value">${Math.round(this.state.settings.musicVolume*100)} %</output></label><p class="music-note">Onze thèmes chiptune originaux accompagnent les lieux et les modes. La musique se met en pause quand l’onglet est masqué.</p><div class="setting-row"><span>Effets sonores</span><button data-act="toggle-sound">${this.state.settings.sound?'Activés':'Désactivés'}</button></div><div class="setting-row"><span>Animations réduites</span><button data-act="toggle-motion">${this.state.settings.reducedMotion?'Activées':'Désactivées'}</button></div><p>Ta progression est sauvegardée sur ce navigateur. Les anciens tickets régionaux sont devenus des tickets universels.</p><button data-act="export-save">Exporter la sauvegarde</button><p class="muted">Sprites : PMD SpriteCollab et ses artistes · CC BY-NC 4.0.<br>Données : PokéAPI. Pokémon © Nintendo / Creatures / GAME FREAK.</p><a href="CREDITS.md" target="_blank" rel="noopener">Crédits et licences →</a>`)}
 exportSave(){const url=URL.createObjectURL(new Blob([JSON.stringify(this.state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='la-tour-infernale-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 bind(){this.modal.addEventListener('cancel',e=>{e.preventDefault();this.closeModal()});document.addEventListener('change',e=>{if(e.target.matches('select[data-library-filter]'))this.library.change(e.target);if(e.target.id==='music-volume')this.audio.music.setVolume(+e.target.value/100)});document.addEventListener('input',e=>{if(e.target.id==='music-volume'){this.audio.music.setVolume(+e.target.value/100,false);document.querySelector('#music-volume-value').textContent=e.target.value+' %'}if(e.target.matches('[data-library-filter="query"]')){clearTimeout(this.libraryTimer);const input=e.target;this.libraryTimer=setTimeout(()=>this.library.change(input),180)}});document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;this.action(b.dataset.act,b.dataset).catch(error=>{console.error(error);this.toast('Une erreur est survenue. Ta progression reste sauvegardée.')})});addEventListener('keydown',e=>{if((this.battle.active||this.duel.active)&&!(this.duel.active?this.duel:this.battle).busy&&!this.modal.open&&/^Digit[1-4]$/.test(e.code)){e.preventDefault();(this.duel.active?this.duel:this.battle).act({move:+e.code.slice(-1)-1})}})}
 async action(act,d){if(act==='legendary-video-play')return this.cinema.videoPlayer.start();if(act==='legendary-video-retry')return this.cinema.videoPlayer.retry();if(act==='legendary-video-continue')return this.cinema.videoPlayer.finish('error');if(act.startsWith('library-'))return this.library.action(act,d);if(['lab-pick-item','lab-pick-move','lab-picker-back','lab-slot-item','lab-slot-move'].includes(act))return this.lab.action(act,d);if(act==='evolution-start')return this.evolutions.start(d.key,+d.index);if(act==='evolution-cancel')return this.evolutions.cancel();if(act==='shop-buy')return this.shop.buy(d);if(act==='shop-use')return this.shop.use(d.key);if(act==='shop-target')return this.shop.target(d);if(act==='toggle-music'){this.audio.music.toggle();return}if(act==='legendary-skip'){this.cinema.finish();return}if(act==='legendary-pause'){this.cinema.pause();return}if(act==='legendary-replay'){await this.cinema.play({key:d.key},{replay:true});this.lab.open(d.key);return}if(act==='legendary-pending'){await this.summoning.resumePending();return}if(act==='arena-stage'||act==='arena-format'){this.duel.clean();if(act==='arena-stage')this.state.settings.arenaTheme=['grass','dirt','ruins','cavern'].includes(d.stage)?d.stage:'grass';else this.state.settings.arenaFormat=d.format==='squad'?'squad':'duel';this.save();this.render();return}if(act==='battle-info'){showCombatInfo(this.duel.active?this.duel:this.battle);return}if(act==='combat-style'){this.duel.clean();this.duel.style=d.style==='arena'?'arena':'classic';this.state.settings.combatStyle=this.duel.style;this.save();this.render();return}if(act==='arena-solo'){this.arena.startSolo();return}if(act.startsWith('arena-')){this.arena.action(act,d);return}if(act.startsWith('conq-')||act.startsWith('cq-'))return this.conquest.action(act,d);switch(act){case'route':this.route(d.page);break;case'afk-jump':if(this.afk.active)this.modeRoot.querySelector(d.target)?.scrollIntoView({block:'start',behavior:this.state.settings.reducedMotion?'instant':'smooth'});break;case'afk-click':this.afk.click();break;case'afk-buy':this.afk.buy(d.building);break;case'afk-upgrade':this.afk.upgrade(d.upgrade);break;case'afk-quantity':this.afk.quantity=Number(d.quantity);this.modeRoot.querySelectorAll('.afk-quantity button').forEach(b=>b.classList.toggle('selected',+b.dataset.quantity===this.afk.quantity));this.afk.update();break;case'afk-tab':this.afk.tab=d.tab;this.afk.renderTab();this.afk.update();break;case'afk-ticket':this.afk.exchange('ticket');break;case'afk-fragments':this.afk.exchange('fragments');break;case'afk-golden':this.afk.golden();break;case'afk-prestige':this.afk.preparePrestige();break;case'afk-confirm-prestige':this.afk.confirmPrestige();break;case'afk-stats':this.afk.stats();break;case'afk-exit':this.afk.stop();break;case'starter-region':this.openStarter(+d.gen);break;case'choose-starter':this.chooseStarter(d.key);break;case'close-modal':this.closeModal();break;case'select-survivor':if(!this.state.roster.includes(d.key))break;this.state.survivor=d.key;this.save();this.render();break;case'toggle-team':if(!this.state.roster.includes(d.key))break;if(this.state.team.includes(d.key)){if(this.state.team.length===1)return this.toast('Garde au moins un Pokémon.');this.state.team=this.state.team.filter(k=>k!==d.key)}else{if(this.state.team.length===6)return this.toast('Ton équipe compte déjà six Pokémon.');this.state.team.push(d.key)}this.save();this.render();break;case'inspect':this.inspect(d.key);break;case'equip':if(equip(this.state,d.uid,document.querySelector('#equip-'+d.index).value)){this.save();this.render();this.toast('Objet équipé.')}else this.toast('Trois objets différents maximum par Pokémon. Retire un objet ou choisis un autre type.');break;case'unequip':unequip(this.state,d.key,d.uid||null);this.save();this.render();break;case'start-run':if(this.requireStarter())this.survival.start();break;case'pause-run':this.survival.paused?this.survival.resume('menu'):this.survival.pause('menu');break;case'resume-run':this.survival.resume('menu');break;case'exit-run':this.survival.finish();break;case'select-move':this.survival.select(+d.slot+1);break;case'open-chest':this.survival.openChest();break;case'upgrade':this.survival.upgrade(d.kind);break;case'start-den':if(this.requireStarter())this.battle.start('den');break;case'duel-create':this.duel.create();break;case'duel-join':this.duel.create(document.querySelector('#duel-code').value.trim());break;case'duel-search':this.duel.search();break;case'duel-cancel':this.duel.clean();this.render();break;case'duel-copy':try{await navigator.clipboard.writeText(this.duel.peer.id);this.toast('Code copié.')}catch{}break;case'lab-equipment':case'lab-equip':case'lab-unequip':case'lab-tab':case'lab-bag':case'train-gold':case'train-candy':case'train-ev':case'train-iv':case'train-nature':case'train-ability':case'train-moves':case'train-evolve':this.lab.action(act,d);break;case'profile-avatar':this.profileDraft={name:document.querySelector('#player-name').value,avatar:d.avatar};this.render();break;case'profile-save':this.state.player=normalizePlayer({name:document.querySelector('#player-name').value,avatar:this.profileDraft?.avatar||this.state.player.avatar});this.profileDraft=null;this.save();this.render();this.toast('Profil enregistré.');break;case'start-battle':if(this.requireStarter())this.battle.start();break;case'battle-move':(this.duel.active?this.duel:this.battle).act({move:+d.slot});break;case'battle-swap':(this.duel.active?this.duel:this.battle).act({swap:+d.slot});break;case'exit-battle':case'finish-battle':if(this.duel.active){this.duel.stop();break}if(this.net.guest){this.net.host?.close();this.net.reset()}else if(!this.net.guest)this.net.broadcast({type:'battle-end-room'});this.battle.stop();break;case'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else this.requestFullscreen();break;case'portal':this.summoning.gen=+d.gen;this.render();break;case'summon-ten':await this.summoning.invoke(10);break;case'summon-next':this.summoning.next();break;case'summon-skip':this.summoning.skip();break;case'summon-again-ten':this.closeModal();await this.summoning.invoke(10);break;case'summon':await this.summoning.invoke();break;case'summon-again':this.closeModal();await this.summoning.invoke();break;case'rates':this.summoning.rates();break;case'create-room':if(this.requireStarter())this.net.create();break;case'join-room':if(this.requireStarter())this.net.join(document.querySelector('#room-code').value);break;case'copy-room':try{await navigator.clipboard.writeText(this.net.peer.id);this.toast('Code du salon copié.')}catch{this.toast('Sélectionne le code pour le copier.')}break;case'settings':this.settings();break;case'toggle-sound':this.state.settings.sound=!this.state.settings.sound;this.save();this.settings();this.audio.tone(440);break;case'toggle-motion':this.state.settings.reducedMotion=!this.state.settings.reducedMotion;document.body.classList.toggle('reduced-motion',this.state.settings.reducedMotion);this.save();this.settings();break;case'export-save':this.exportSave();break}}
}
async function boot(){try{const [a,b,c,p]=await Promise.all([fetch('data/dex.json'),fetch('data/types.json'),fetch('data/supported.json'),fetch('data/progression.json')]);if(!a.ok||!b.ok)throw Error('Données locales indisponibles');const rawDex=await a.json(),supported=await c.json();const dex=Object.fromEntries(supported.filter(p=>rawDex[p.id]).map(p=>[p.id,{...rawDex[p.id],shiny:p.shiny}]));const progression=await p.json();for(const d of Object.values(dex)){d.evolutions=progression.evolutions[d.id]||[];if(SUMMON_RARITIES[d.id])d.rarity=SUMMON_RARITIES[d.id];d.tmMoves=progression.tmLearnsets[d.id]||[]}const game=new GameApp(dex,await b.json(),progression);window.Game=game;document.body.classList.toggle('reduced-motion',game.state.settings.reducedMotion);document.querySelector('#boot-screen')?.remove()}catch(e){console.error(e);document.querySelector('#content').innerHTML='<section class="panel empty-state"><h1>La tour est momentanément inaccessible.</h1><p>Les données du jeu n’ont pas pu être chargées. Recharge la page pour réessayer.</p><button onclick="location.reload()">Réessayer</button></section>';document.querySelector('#boot-screen')?.remove()}}
boot();
